css:
.cpa-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #232a35;
    background: linear-gradient(165deg, #f7f4ec 0%, #f1ede2 55%, #ece7d8 100%);
    border-radius: 18px;
}

.cpa-container * {
    box-sizing: border-box;
}

.cpa-header {
    text-align: center;
    padding: 30px 24px 26px;
    background: linear-gradient(135deg, #14233f 0%, #1f3a63 60%, #2b4a78 100%);
    color: #f4f1e8;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(20, 35, 63, 0.32);
    border-bottom: 4px solid #b8902f;
}

.cpa-header h1 {
    margin: 10px 0 10px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 2.5rem;
    font-weight: 700;
    letter-spacing: -0.4px;
    color: #ffffff;
}

.cpa-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.4px;
    font-weight: 700;
    color: #e7c873;
    background: rgba(231, 200, 115, 0.12);
    border: 1px solid rgba(231, 200, 115, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.cpa-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d6dce8;
}

.cpa-client {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.cpa-client-card {
    flex: 1;
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(35, 42, 53, 0.08);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.cpa-client-meridian { border-left: 5px solid #1f3a63; }
.cpa-client-halford { border-left: 5px solid #b8902f; }

.cpa-client-name {
    font-family: Georgia, 'Times New Roman', serif;
    font-weight: 700;
    font-size: 1.08rem;
    color: #14233f;
}

.cpa-client-halford .cpa-client-name { color: #8a6a1a; }

.cpa-client-meta {
    font-size: 0.82rem;
    color: #5c6573;
    line-height: 1.4;
}

.cpa-client-arrow {
    align-self: center;
    font-size: 1.7rem;
    font-weight: 800;
    color: #2b4a78;
}

.cpa-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #45505f;
    margin-bottom: 16px;
    padding: 4px;
}

.cpa-period-counter #currentDay,
.cpa-period-counter #maxPeriods {
    font-weight: 800;
    color: #1f3a63;
}

.cpa-round-name {
    background: rgba(31, 58, 99, 0.12);
    color: #1f3a63;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.cpa-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a6a1a;
    background: rgba(184, 144, 47, 0.14);
    border: 1px solid rgba(184, 144, 47, 0.32);
    padding: 4px 12px;
    border-radius: 999px;
}

.cpa-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.cpa-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(35, 42, 53, 0.08);
    border-top: 4px solid #1f3a63;
}

.cpa-card-align { border-top-color: #1f3a63; }
.cpa-card-behaviour { border-top-color: #2f8f6a; }
.cpa-card-satisfaction { border-top-color: #b8902f; }
.cpa-card-budget { border-top-color: #6a5acd; }

.cpa-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a7585;
}

.cpa-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #14233f;
    font-variant-numeric: tabular-nums;
}

.cpa-card-align .cpa-value { color: #1f3a63; }
.cpa-card-behaviour .cpa-value { color: #2f8f6a; }
.cpa-card-satisfaction .cpa-value { color: #a07d1e; }
.cpa-card-budget .cpa-value { color: #6a5acd; }

.cpa-sublabel {
    font-size: 0.75rem;
    color: #79839a;
    line-height: 1.35;
}

/* Behaviour card states — the renewal-gating KPI tells the strongest story. */
.cpa-card-behaviour.cpa-behaviour-good { border-top-color: #2f8f6a; }
.cpa-card-behaviour.cpa-behaviour-good .cpa-value { color: #2f8f6a; }
.cpa-card-behaviour.cpa-behaviour-bad { border-top-color: #c0392b; }
.cpa-card-behaviour.cpa-behaviour-bad .cpa-value { color: #c0392b; }

/* Budget card turns red when committed spend exceeds the fixed envelope. */
.cpa-card-budget.cpa-budget-over { border-top-color: #c0392b; }
.cpa-card-budget.cpa-budget-over .cpa-value { color: #c0392b; }

.cpa-risk-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #e3ddcd;
    color: #45505f;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.cpa-risk-bar #riskDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #c0392b;
    font-weight: 800;
}

.cpa-risk-bar.cpa-risk-low #riskDisplay { color: #2f8f6a; }
.cpa-risk-bar.cpa-risk-mid #riskDisplay { color: #a07d1e; }

.cpa-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #b8902f;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(35, 42, 53, 0.07);
}

.cpa-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.cpa-briefing-title {
    font-family: Georgia, 'Times New Roman', serif;
    font-weight: 700;
    font-size: 1.12rem;
    color: #14233f;
    margin-bottom: 6px;
}

.cpa-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a4453;
}

.cpa-briefing-text strong { color: #1f3a63; }
.cpa-briefing-text em { color: #8a6a1a; font-style: italic; }

.cpa-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(35, 42, 53, 0.07);
}

.cpa-controls h3 {
    margin: 0 0 14px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 1.16rem;
    font-weight: 700;
    color: #14233f;
    border-bottom: 2px solid #ece6d7;
    padding-bottom: 8px;
}

.cpa-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2b3645;
    margin: 14px 0 6px;
}

.cpa-container select,
.cpa-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cdc6b5;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #232a35;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.cpa-container select:focus,
.cpa-container input[type="number"]:focus {
    outline: none;
    border-color: #1f3a63;
    box-shadow: 0 0 0 3px rgba(31, 58, 99, 0.15);
}

.cpa-container select option {
    background-color: #ffffff;
    color: #232a35;
}

.cpa-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #1f3a63;
}

.cpa-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #45505f;
    margin-top: 4px;
}

.cpa-range-readout span:nth-child(2) {
    color: #1f3a63;
    font-weight: 800;
}

.cpa-hint {
    font-size: 0.8rem;
    color: #79839a;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.cpa-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.cpa-container .btn-primary {
    background: linear-gradient(135deg, #1f3a63 0%, #2b4a78 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(31, 58, 99, 0.30);
}

.cpa-container .btn-primary:hover {
    filter: brightness(1.10);
}

.cpa-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #cdc6b5;
    color: #5c6573;
    background: transparent;
}

.cpa-coach {
    background: linear-gradient(160deg, #14233f 0%, #1c3052 100%);
    color: #e6ddc9;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(20, 35, 63, 0.26);
    border-left: 5px solid #b8902f;
}

.cpa-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e7c873;
    margin-bottom: 8px;
}

.cpa-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.cpa-coach-body strong { color: #f0d488; }
.cpa-coach-body em { color: #9fd4bd; font-style: italic; }

.cpa-history,
.cpa-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(35, 42, 53, 0.07);
}

.cpa-history h3,
.cpa-chart h3 {
    margin: 0 0 14px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 1.12rem;
    font-weight: 700;
    color: #14233f;
}

.cpa-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a4453;
}

.cpa-container table#usfHistoryTable th {
    background: #f3eee2;
    color: #1f3a63;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e1d9c6;
}

.cpa-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #efeade;
    color: #3a4453;
}

.cpa-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf7ef;
}

.cpa-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .cpa-container {
        padding: 14px;
    }
    .cpa-header h1 {
        font-size: 1.8rem;
    }
    .cpa-client {
        flex-direction: column;
    }
    .cpa-client-arrow {
        transform: rotate(90deg);
    }
    .cpa-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .cpa-value {
        font-size: 2rem;
    }
    .cpa-clock {
        margin-left: 0;
    }
    .cpa-period-counter {
        font-size: 0.88rem;
    }
    .cpa-risk-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .cpa-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion debrief (append-only, cpa-cm-*) ===== */
.cpa-cm { color: #23303c; font-family: inherit; }
.cpa-cm-generic { font-size: 15px; text-align: center; }
.cpa-cm-scoreband { text-align: center; padding: 6px 0 14px; border-bottom: 1px solid rgba(35,48,60,0.12); margin-bottom: 16px; }
.cpa-cm-score { font-size: 46px; font-weight: 700; line-height: 1; color: #3f6fb0; }
.cpa-cm-score-max { font-size: 20px; font-weight: 500; color: #7c8896; margin-left: 2px; }
.cpa-cm-tier { font-size: 20px; font-weight: 600; margin-top: 6px; color: #23303c; }
.cpa-cm-caption { font-size: 11.5px; letter-spacing: .05em; text-transform: uppercase; color: #7c8896; margin-top: 4px; }
.cpa-cm-kpis { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin-bottom: 14px; }
.cpa-cm-kpi { flex: 1 1 92px; min-width: 92px; background: rgba(63,111,176,0.07); border: 1px solid rgba(63,111,176,0.18); border-radius: 10px; padding: 10px 8px; text-align: center; }
.cpa-cm-kpi-val { display: block; font-size: 20px; font-weight: 700; color: #23303c; }
.cpa-cm-kpi-lbl { display: block; font-size: 11px; margin-top: 3px; color: #55636e; }
.cpa-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; margin-bottom: 14px; }
.cpa-cm-chip { font-size: 12.5px; font-weight: 600; padding: 5px 11px; border-radius: 999px; border: 1px solid transparent; }
.cpa-cm-chip.is-met { background: rgba(46,143,107,0.14); border-color: rgba(46,143,107,0.42); color: #1f6e50; }
.cpa-cm-chip.is-missed { background: rgba(197,74,74,0.12); border-color: rgba(197,74,74,0.4); color: #a23b3b; }
.cpa-cm-insights { margin: 0; padding-left: 18px; }
.cpa-cm-insights li { font-size: 13.5px; line-height: 1.5; color: #38434e; margin-bottom: 7px; }

