(function() {
    'use strict';

    class CustomProgramArchitectAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Custom Program Architect`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Meridian / Halford Industrial).
            this.PARTICIPANTS = 220;            // mid-level managers
            this.BUDGET = 480000;               // GBP fixed, non-negotiable
            this.PER_HEAD = 2182;               // 480,000 / 220
            this.COST_RESIDENTIAL = 3400;       // per head, premium, unaffordable at 220
            this.COST_BLENDED = 1850;           // per head, balanced (incl. workplace projects)
            this.COST_DIGITAL = 950;            // per head, cheapest, weakest on behaviour
            this.MEASUREMENT_COST = 45000;      // Level 3/4 evidence build
            this.APPLICATION_COST = 20000;      // incremental 70-20-10 application mechanism on a blended base
            this.FACULTY_DAYS = 18;             // top-3 GM faculty available
            this.ACCOUNT_VALUE = 1.4;           // GBP M three-year account
            this.CHECKPOINT_DAYS = 90;          // renewal gate

            // Starting KPIs.
            this.START_ALIGN = 50;
            this.START_BEHAVIOUR = 30;
            this.START_SATISFACTION = 60;

            // Concept truths.
            this.TRUE_NEED = `diagnosed`;
            this.TRUE_FORMAT = `blended`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    align: this.START_ALIGN,            // needs-alignment score (%)
                    behaviour: this.START_BEHAVIOUR,    // projected Kirkpatrick L3 behaviour change (%)
                    satisfaction: this.START_SATISFACTION, // Kirkpatrick L1 client satisfaction (%)
                    budgetSpent: 0,                     // GBP committed against the 480,000 envelope
                    risk: 78,                           // renewal-risk index 0–100 (lower is safer)

                    // Sticky, run-defining penalty flags — set when the error is committed,
                    // they GATE the top verdict and CAP KPIs (a later good round cannot wash them out).
                    orderTaking: false,                 // designed to the stated brief, not the diagnosed need
                    budgetBlown: false,                 // committed spend exceeds the fixed envelope
                    measurementCut: false,              // no Level 3/4 evidence plan funded
                    noApplication: false,               // no 70-20-10 workplace-application mechanism
                    overPromised: false,                // guaranteed outcomes the design can't deliver
                    satisfactionFirst: false,           // optimised for Level 1 over Level 3
                    digitalOnly: false,                 // chose the weakest-on-behaviour format

                    format: ``,                         // chosen delivery format
                    alignHistory: [this.START_ALIGN],
                    behaviourHistory: [this.START_BEHAVIOUR],
                    satisfactionHistory: [this.START_SATISFACTION],
                    budgetHistory: [0],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    need: `stated`,
                    outcome: `knowledge`,
                    content: `all`,
                    align: 35,
                    format: `residential`,
                    faculty: `overbook`,
                    design: `220000`,
                    delivery: 240000,
                    measure: `cut`,
                    application: `none`,
                    metrics: `reaction`,
                    split: 10,
                    pitch: `satisfaction`,
                    promise: `guarantee`,
                    defend: `deny`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const ne = document.getElementById(`needInput`);
                const ou = document.getElementById(`outcomeInput`);
                const co = document.getElementById(`contentInput`);
                const al = document.getElementById(`alignInput`);
                if (ne) decisions.need = ne.value;
                if (ou) decisions.outcome = ou.value;
                if (co) decisions.content = co.value;
                if (al) decisions.align = parseInt(al.value, 10);
                if (!Number.isFinite(decisions.align) || decisions.align < 0 || decisions.align > 100) {
                    warn(`warn_align_range`); return false;
                }
            } else if (round === 2) {
                const fo = document.getElementById(`formatInput`);
                const fa = document.getElementById(`facultyInput`);
                const de = document.getElementById(`designInput`);
                const dl = document.getElementById(`deliveryInput`);
                if (fo) decisions.format = fo.value;
                if (fa) decisions.faculty = fa.value;
                if (de) decisions.design = de.value;
                if (dl) decisions.delivery = parseFloat(dl.value);
                if (!Number.isFinite(decisions.delivery) || decisions.delivery < 0) {
                    warn(`warn_delivery_value`); return false;
                }
            } else if (round === 3) {
                const me = document.getElementById(`measureInput`);
                const ap = document.getElementById(`applicationInput`);
                const mt = document.getElementById(`metricsInput`);
                const sp = document.getElementById(`splitInput`);
                if (me) decisions.measure = me.value;
                if (ap) decisions.application = ap.value;
                if (mt) decisions.metrics = mt.value;
                if (sp) decisions.split = parseInt(sp.value, 10);
                if (!Number.isFinite(decisions.split) || decisions.split < 0 || decisions.split > 100) {
                    warn(`warn_split_range`); return false;
                }
            } else if (round === 4) {
                const pi = document.getElementById(`pitchInput`);
                const pr = document.getElementById(`promiseInput`);
                const df = document.getElementById(`defendInput`);
                const cv = document.getElementById(`convictionInput`);
                if (pi) decisions.pitch = pi.value;
                if (pr) decisions.promise = pr.value;
                if (df) decisions.defend = df.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let alignDelta = 0, behaviourDelta = 0, satisfactionDelta = 0, riskDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the real need (Common Error 1: order-taking).
                switch (d.need) {
                    case `diagnosed`:
                        alignDelta += 22; behaviourDelta += 8; riskDelta -= 14; coachKey = `coach_r1_diagnosed`; break;
                    case `stated`:
                        // STICKY: designing to the RFP brief, not the diagnosed challenge.
                        ds.orderTaking = true;
                        alignDelta -= 6; satisfactionDelta += 5; riskDelta += 8; coachKey = `coach_r1_stated`; break;
                    case `topics`:
                        ds.orderTaking = true;
                        alignDelta -= 4; satisfactionDelta += 3; riskDelta += 7; coachKey = `coach_r1_topics`; break;
                }

                switch (d.outcome) {
                    case `behaviour`: alignDelta += 10; behaviourDelta += 6; riskDelta -= 6; break;
                    case `knowledge`: alignDelta -= 3; riskDelta += 4; if (coachKey === `coach_default`) coachKey = `coach_r1_knowledge`; break;
                    case `satisfaction`: ds.satisfactionFirst = true; satisfactionDelta += 4; alignDelta -= 5; riskDelta += 5; break;
                }

                switch (d.content) {
                    case `cut`: alignDelta += 7; behaviourDelta += 3; riskDelta -= 4; break;
                    case `all`: alignDelta -= 4; satisfactionDelta += 3; riskDelta += 4; break;
                    case `none`: alignDelta -= 6; behaviourDelta -= 4; satisfactionDelta -= 4; riskDelta += 5; break;
                }

                // Diagnostic rigour — the discipline of scoring brief-vs-need before designing.
                if (d.align >= 60) { alignDelta += 6; riskDelta -= 4; }
                else if (d.align <= 25) { alignDelta -= 4; riskDelta += 4; }

                summaryKey = (d.need === `diagnosed` && d.outcome === `behaviour` && d.content === `cut`) ? `sum_r1_good` : `sum_r1_weak`;
                if (d.need === `diagnosed` && d.outcome === `behaviour`) coachKey = `coach_r1_sharp`;
            } else if (round === 2) {
                // Choose the delivery format & allocate the envelope (Common Error 2: format-as-aspiration).
                let formatHead = 0;
                switch (d.format) {
                    case `blended`: formatHead = this.COST_BLENDED; break;
                    case `residential`: formatHead = this.COST_RESIDENTIAL; break;
                    case `digital`: formatHead = this.COST_DIGITAL; break;
                }
                ds.format = d.format;
                const formatTotal = formatHead * this.PARTICIPANTS;

                // Budget committed this round = format bundle (design+delivery+faculty live inside it).
                // The "design" and "delivery" levers tune quality WITHIN that bundle, not on top of it,
                // except where they push total spend above the format floor.
                const designSpend = parseFloat(d.design) || 0;
                const deliverySpend = Number.isFinite(d.delivery) ? d.delivery : 0;
                // Effective committed spend: the format floor, plus any design/delivery over-commitment.
                const overCommit = Math.max(0, (designSpend + deliverySpend) - formatTotal);
                ds.budgetSpent = Math.round(formatTotal + overCommit);

                switch (d.format) {
                    case `blended`:
                        alignDelta += 8; behaviourDelta += 16; satisfactionDelta += 6; riskDelta -= 12; coachKey = `coach_r2_blended`; break;
                    case `residential`:
                        // STICKY: premium format cannot be afforded at 220 heads.
                        ds.budgetBlown = true;
                        alignDelta += 2; behaviourDelta += 10; satisfactionDelta += 12; riskDelta += 10; coachKey = `coach_r2_residential`; break;
                    case `digital`:
                        ds.digitalOnly = true;   // weakest-on-behaviour format — caps the behaviour KPI below the win bar
                        alignDelta += 2; behaviourDelta -= 6; satisfactionDelta -= 6; riskDelta += 8; coachKey = `coach_r2_digital`; break;
                }

                // Faculty constraint (18 days vs 40+ demand).
                switch (d.faculty) {
                    case `leverage`: behaviourDelta += 6; riskDelta -= 6; satisfactionDelta += 2; break;
                    case `overbook`: ds.overPromised = true; riskDelta += 8; behaviourDelta -= 4; coachKey = `coach_r2_overbook`; break;
                    case `dilute`: behaviourDelta -= 6; satisfactionDelta -= 5; riskDelta += 5; coachKey = `coach_r2_dilute`; break;
                }

                // Design allocation — heavy bespoke content crowds out measurement & application.
                switch (d.design) {
                    case `60000`: behaviourDelta += 2; break;
                    case `120000`: alignDelta += 2; satisfactionDelta += 3; break;
                    case `220000`: satisfactionDelta += 8; alignDelta -= 3; riskDelta += 5; coachKey = (coachKey === `coach_default`) ? `coach_r2_designheavy` : coachKey; break;
                }

                // Over the fixed envelope at any point = sticky budget-blown.
                if (ds.budgetSpent > this.BUDGET) {
                    ds.budgetBlown = true;
                    if (d.format !== `residential`) coachKey = `coach_r2_overbudget`;
                }

                summaryKey = (d.format === `blended` && d.faculty === `leverage` && ds.budgetSpent <= this.BUDGET) ? `sum_r2_good` :
                             (d.format === `residential` ? `sum_r2_residential` :
                             (d.format === `digital` ? `sum_r2_digital` :
                             (ds.budgetSpent > this.BUDGET ? `sum_r2_overbudget` : `sum_r2_weak`)));
            } else if (round === 3) {
                // Engineer measurable impact (Common Errors 3 & 4).
                // Measurement build.
                switch (d.measure) {
                    case `full`:
                        ds.budgetSpent = Math.round(ds.budgetSpent + this.MEASUREMENT_COST);
                        behaviourDelta += 8; alignDelta += 6; riskDelta -= 14; break;
                    case `level1`:
                        ds.measurementCut = true; // no Level 3/4 evidence
                        satisfactionDelta += 4; riskDelta += 8; coachKey = `coach_r3_level1`; break;
                    case `cut`:
                        // STICKY: stripped the evidence plan to add content.
                        ds.measurementCut = true;
                        satisfactionDelta += 6; behaviourDelta += 2; riskDelta += 12; coachKey = `coach_r3_cut`; break;
                }

                // 70-20-10 workplace application.
                switch (d.application) {
                    case `builtin`:
                        ds.budgetSpent = Math.round(ds.budgetSpent + this.APPLICATION_COST);
                        behaviourDelta += 18; alignDelta += 6; riskDelta -= 12; break;
                    case `optional`:
                        ds.noApplication = true;
                        behaviourDelta += 3; riskDelta += 4; coachKey = (coachKey === `coach_default`) ? `coach_r3_optional` : coachKey; break;
                    case `none`:
                        // STICKY: content without application — behaviour never shifts.
                        ds.noApplication = true;
                        behaviourDelta -= 8; satisfactionDelta += 3; riskDelta += 10; coachKey = `coach_r3_noapp`; break;
                }

                // Metrics anchored to the outcome statement.
                switch (d.metrics) {
                    case `behaviour`: alignDelta += 6; behaviourDelta += 5; riskDelta -= 8; break;
                    case `completion`: alignDelta -= 1; riskDelta += 3; break;
                    case `reaction`: ds.satisfactionFirst = true; satisfactionDelta += 3; alignDelta -= 4; riskDelta += 6; coachKey = (coachKey === `coach_default`) ? `coach_r3_reaction` : coachKey; break;
                }

                // Commitment of remaining budget to measurement & application.
                if (d.split >= 25) { behaviourDelta += 5; riskDelta -= 5; alignDelta += 3; }
                else if (d.split <= 5) { behaviourDelta -= 4; riskDelta += 5; if (coachKey === `coach_default`) coachKey = `coach_r3_lowsplit`; }

                // Re-check the envelope after the measurement/application adds.
                if (ds.budgetSpent > this.BUDGET) {
                    ds.budgetBlown = true;
                    coachKey = `coach_r3_overbudget`;
                }

                if (d.measure === `full` && d.application === `builtin` && d.metrics === `behaviour`) coachKey = `coach_r3_impact`;

                summaryKey = (d.measure === `full` && d.application === `builtin` && d.metrics === `behaviour`) ? `sum_r3_good` :
                             (ds.measurementCut ? `sum_r3_nomeasure` :
                             (ds.noApplication ? `sum_r3_noapp` : `sum_r3_weak`));
            } else if (round === 4) {
                // Pitch the architecture to the board sponsor (Common Errors 5 & over-promising).
                switch (d.pitch) {
                    case `behaviour`: alignDelta += 8; behaviourDelta += 4; riskDelta -= 10; coachKey = `coach_r4_behaviour`; break;
                    case `satisfaction`: ds.satisfactionFirst = true; satisfactionDelta += 8; alignDelta -= 4; riskDelta += 8; coachKey = `coach_r4_satisfaction`; break;
                    case `content`: satisfactionDelta += 4; alignDelta -= 2; riskDelta += 5; coachKey = `coach_r4_content`; break;
                }

                switch (d.promise) {
                    case `credible`: alignDelta += 6; behaviourDelta += 4; riskDelta -= 10; break;
                    case `guarantee`: ds.overPromised = true; satisfactionDelta += 4; riskDelta += 12; behaviourDelta -= 2; coachKey = `coach_r4_overpromise`; break;
                    case `vague`: alignDelta -= 4; riskDelta += 6; coachKey = (coachKey === `coach_default`) ? `coach_r4_vague` : coachKey; break;
                }

                switch (d.defend) {
                    case `own`: alignDelta += 6; riskDelta -= 8; behaviourDelta += 2; if (d.pitch === `behaviour`) coachKey = `coach_r4_own`; break;
                    case `deny`: riskDelta += 6; alignDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r4_deny` : coachKey; break;
                    case `content`: ds.measurementCut = ds.measurementCut; riskDelta += 7; alignDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_defendcontent` : coachKey; break;
                }

                if (d.conviction >= 60) { alignDelta += 3; riskDelta -= 4; }
                else if (d.conviction <= 25) { alignDelta -= 3; riskDelta += 4; }

                summaryKey = (d.pitch === `behaviour` && d.promise === `credible` && d.defend === `own`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply KPI deltas (clamped). ----
            ds.align = Math.max(0, Math.min(100, Math.round(ds.align + alignDelta)));
            ds.behaviour = Math.max(0, Math.min(100, Math.round(ds.behaviour + behaviourDelta)));
            ds.satisfaction = Math.max(0, Math.min(100, Math.round(ds.satisfaction + satisfactionDelta)));
            ds.risk = Math.max(0, Math.min(100, Math.round(ds.risk + riskDelta)));

            // ---- STICKY PENALTY CAPS — the headline anti-patterns cannot reach the top verdict,
            // and a later strong round cannot wash them out. Caps bite the renewal-gating KPIs. ----
            if (ds.orderTaking) {
                ds.align = Math.min(ds.align, 55);            // designed to the wrong need
                ds.behaviour = Math.min(ds.behaviour, 50);
            }
            if (ds.budgetBlown) {
                ds.align = Math.min(ds.align, 60);            // a proposal that doesn't fit the fixed budget
                ds.risk = Math.max(ds.risk, 60);
            }
            if (ds.measurementCut) {
                ds.behaviour = Math.min(ds.behaviour, 48);    // cannot prove behaviour change at 90 days
                ds.risk = Math.max(ds.risk, 62);
            }
            if (ds.noApplication) {
                ds.behaviour = Math.min(ds.behaviour, 45);    // the 70-20-10 trap — behaviour never shifts
            }
            if (ds.overPromised) {
                ds.risk = Math.max(ds.risk, 58);              // outcomes the design can't deliver
            }
            if (ds.satisfactionFirst && (ds.measurementCut || ds.noApplication)) {
                ds.behaviour = Math.min(ds.behaviour, 42);    // optimised Level 1 while Level 3 is the gate
            }
            if (ds.digitalOnly) {
                ds.behaviour = Math.min(ds.behaviour, 60);    // self-paced digital can't carry behaviour past the win bar
            }

            ds.alignHistory.push(ds.align);
            ds.behaviourHistory.push(ds.behaviour);
            ds.satisfactionHistory.push(ds.satisfaction);
            ds.budgetHistory.push(ds.budgetSpent);

            // ---- Persist composite where the grading/reporting layer reads it ----
            const _score = this._composite(ds);
            ds.score = _score;
            ds.performance = ds.performance || {};
            ds.performance.overallScore = _score;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                overallScore: _score,
                score: _score,
                align: ds.align,
                alignDelta: Math.round(alignDelta),
                behaviour: ds.behaviour,
                behaviourDelta: Math.round(behaviourDelta),
                satisfaction: ds.satisfaction,
                budgetSpent: ds.budgetSpent,
                budgetBlown: ds.budgetBlown,
                risk: ds.risk,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _riskLabel(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (v >= 60) return t(`risk_high`);
            if (v >= 35) return t(`risk_mid`);
            return t(`risk_low`);
        }

        _fmtGBP(v) {
            // GBP, thousands grouped, locale-aware separators (en "£480,000", es "£480.000").
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Math.round(Number(v) || 0);
            const grouped = n.toLocaleString(lang === `es` ? `es-ES` : `en-GB`);
            return `£` + grouped;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`alignDisplay`, `domainState.align`, (v) => `${Math.round(Number(v))}%`);

            uiManager.bind(`behaviourDisplay`, `domainState.behaviour`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.cpa-card-behaviour`);
                if (card) {
                    card.classList.toggle(`cpa-behaviour-bad`, n < 50);
                    card.classList.toggle(`cpa-behaviour-good`, n >= 65);
                }
                return `${n}%`;
            });

            uiManager.bind(`satisfactionDisplay`, `domainState.satisfaction`, (v) => `${Math.round(Number(v))}%`);

            uiManager.bind(`budgetDisplay`, `domainState.budgetSpent`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.cpa-card-budget`);
                if (card) card.classList.toggle(`cpa-budget-over`, n > self.BUDGET);
                return self._fmtGBP(n);
            });

            uiManager.bind(`riskDisplay`, `domainState.risk`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.cpa-risk-bar`);
                if (bar) {
                    bar.classList.toggle(`cpa-risk-low`, n < 35);
                    bar.classList.toggle(`cpa-risk-mid`, n >= 35 && n < 60);
                }
                return self._riskLabel(n);
            });

            // Alignment-rigour slider readout (Round 1).
            const al = document.getElementById(`alignInput`);
            const alReadout = document.getElementById(`alignReadout`);
            if (al && alReadout) {
                alReadout.textContent = al.value;
                al.addEventListener(`input`, function() { alReadout.textContent = al.value; });
            }

            // Measurement/application split slider readout (Round 3).
            const sp = document.getElementById(`splitInput`);
            const spReadout = document.getElementById(`splitReadout`);
            if (sp && spReadout) {
                spReadout.textContent = sp.value;
                sp.addEventListener(`input`, function() { spReadout.textContent = sp.value; });
            }
        }

        getChartConfig() {
            return {
                architectChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(`chart_series_align`) : `Needs alignment (%)`,
                                data: [],
                                borderColor: `#1f3a63`,
                                backgroundColor: `rgba(31,58,99,0.10)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#1f3a63`,
                                yAxisID: `y`
                            },
                            {
                                label: (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(`chart_series_behaviour`) : `Projected behaviour change (%)`,
                                data: [],
                                borderColor: `#2f8f6a`,
                                backgroundColor: `rgba(47,143,106,0.10)`,
                                borderWidth: 3,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#2f8f6a`,
                                yAxisID: `y`
                            },
                            {
                                label: (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(`chart_series_satisfaction`) : `Client satisfaction (%)`,
                                data: [],
                                borderColor: `#b8902f`,
                                backgroundColor: `rgba(184,144,47,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#b8902f`,
                                yAxisID: `y`
                            },
                            {
                                label: (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(`chart_series_budget`) : `Budget committed (% of £480k)`,
                                data: [],
                                borderColor: `#6a5acd`,
                                backgroundColor: `rgba(106,90,205,0.08)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#6a5acd`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#45505f`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 120, position: `left`,
                                ticks: { color: `#79839a` }, grid: { color: `rgba(35,42,53,0.06)` },
                                title: { display: true, text: `0–100 (%)`, color: `#79839a` }
                            },
                            x: {
                                ticks: { color: `#79839a` }, grid: { color: `rgba(35,42,53,0.04)` },
                                title: { display: true, text: `Round`, color: `#79839a` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.alignHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // Budget plotted as % of the fixed envelope to share the 0–100 axis.
            const budgetPct = ds.budgetHistory.map((v) => Math.round((v / this.BUDGET) * 100));
            return {
                architectChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.alignHistory },
                        { data: ds.behaviourHistory },
                        { data: ds.satisfactionHistory },
                        { data: budgetPct }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.0.0 completion formula, single source of truth, persisted every period so the
            // grading/analytics/LTI layer (domainState.performance.overallScore then top-level
            // score) receives a number instead of null -> 0.0.
            const align = Math.round(ds.align);
            const behaviour = Math.round(ds.behaviour);
            const satisfaction = Math.round(ds.satisfaction);
            const budgetSpent = Math.round(ds.budgetSpent);
            const inBudget = budgetSpent <= this.BUDGET;
            const budgetScore = inBudget ? 100 : Math.max(0, Math.round(100 - ((budgetSpent - this.BUDGET) / this.BUDGET) * 100));
            return Math.round(behaviour * 0.34 + align * 0.28 + budgetScore * 0.22 + satisfaction * 0.16);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const align = Math.round(ds.align);
            const behaviour = Math.round(ds.behaviour);
            const satisfaction = Math.round(ds.satisfaction);
            const budgetSpent = Math.round(ds.budgetSpent);
            const inBudget = budgetSpent <= this.BUDGET;

            // Budget adherence as a 0–100 score (100 = on or under budget).
            const budgetScore = inBudget ? 100 : Math.max(0, Math.round(100 - ((budgetSpent - this.BUDGET) / this.BUDGET) * 100));

            // Composite weights behaviour heaviest — it is the renewal gate.
            const composite = this._composite(ds);

            const aligned = align >= 70;
            const behaviourStrong = behaviour >= 65;
            const satisfied = satisfaction >= 60;

            // Any sticky flag is set?
            const cleanRun = !ds.orderTaking && !ds.budgetBlown && !ds.measurementCut && !ds.noApplication && !ds.overPromised;

            // ---- TOP VERDICT IS GATED on a clean, in-budget, behaviour-proving run. ----
            let performance = `Account Lost`, performanceKey = `grade_lost`;
            if (cleanRun && inBudget && aligned && behaviourStrong && composite >= 76) {
                performance = `Account Won`; performanceKey = `grade_won`;                 // renewal earned on evidence
            } else if (cleanRun && inBudget && behaviour >= 55 && align >= 60 && composite >= 64) {
                performance = `Renewal Likely`; performanceKey = `grade_renewal`;
            } else if (ds.budgetBlown && !inBudget) {
                performance = `Budget Blown`; performanceKey = `grade_budgetblown`;
            } else if (ds.measurementCut) {
                performance = `Cannot Prove It`; performanceKey = `grade_cannotprove`;
            } else if (ds.noApplication) {
                performance = `Knowledge, Not Behaviour`; performanceKey = `grade_knowledge`;
            } else if (ds.orderTaking) {
                performance = `Built the Wrong Thing`; performanceKey = `grade_wrongthing`;
            } else if (ds.satisfactionFirst && behaviour < 55) {
                performance = `Liked but Unchanged`; performanceKey = `grade_liked`;
            } else if (composite >= 55) {
                performance = `Mixed Proposal`; performanceKey = `grade_mixed`;
            }

            const insights = [];
            if (performance === `Account Won`) insights.push(window.mySimulation.t(`insight_won`));
            else if (ds.orderTaking) insights.push(window.mySimulation.t(`insight_ordertaking`));
            else if (ds.budgetBlown) insights.push(window.mySimulation.t(`insight_budget`));
            else if (ds.measurementCut) insights.push(window.mySimulation.t(`insight_measurement`));
            else if (ds.noApplication) insights.push(window.mySimulation.t(`insight_application`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.satisfactionFirst && behaviour < 55) insights.push(window.mySimulation.t(`insight_satisfaction`));
            if (ds.overPromised) insights.push(window.mySimulation.t(`insight_overpromise`));
            if (behaviour < 50) insights.push(window.mySimulation.t(`insight_behaviour_low`));
            if (!inBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            if (cleanRun && inBudget && behaviour >= 65 && satisfaction < 55) insights.push(window.mySimulation.t(`insight_satisfaction_cost`));

            return {
                align: align,
                behaviour: behaviour,
                satisfaction: satisfaction,
                budgetSpent: budgetSpent,
                budgetScore: budgetScore,
                inBudget: inBudget,
                aligned: aligned,
                behaviourStrong: behaviourStrong,
                satisfied: satisfied,
                cleanRun: cleanRun,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const self = this;
            const t = (window.mySimulation && window.mySimulation.t)
                ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (!summary || typeof summary.composite !== `number`) {
                return `<div class="cpa-cm"><p class="cpa-cm-generic">${t(`cm_generic`)}</p></div>`;
            }
            const tier = summary.performanceKey ? t(summary.performanceKey) : (summary.performance || ``);
            const kpi = (labelKey, valStr) =>
                `<div class="cpa-cm-kpi"><span class="cpa-cm-kpi-val">${valStr}</span>`
                + `<span class="cpa-cm-kpi-lbl">${t(labelKey)}</span></div>`;
            const chip = (ok, labelKey) =>
                `<span class="cpa-cm-chip ${ok ? `is-met` : `is-missed`}">`
                + `${ok ? `✓` : `✗`} ${t(labelKey)}</span>`;
            const insights = (summary.insights || []).map((x) => `<li>${x}</li>`).join(``);
            return ``
                + `<div class="cpa-cm">`
                +   `<div class="cpa-cm-scoreband">`
                +     `<div class="cpa-cm-score">${summary.composite}<span class="cpa-cm-score-max">/100</span></div>`
                +     `<div class="cpa-cm-tier">${tier}</div>`
                +     `<div class="cpa-cm-caption">${t(`cm_caption`)}</div>`
                +   `</div>`
                +   `<div class="cpa-cm-kpis">`
                +     kpi(`cm_kpi_align`, String(Math.round(summary.align)) + `%`)
                +     kpi(`cm_kpi_behaviour`, String(Math.round(summary.behaviour)) + `%`)
                +     kpi(`cm_kpi_satisfaction`, String(Math.round(summary.satisfaction)) + `%`)
                +     kpi(`cm_kpi_budget`, self._fmtGBP(summary.budgetSpent))
                +   `</div>`
                +   `<div class="cpa-cm-chips">`
                +     chip(summary.inBudget, `cm_chip_budget`)
                +     chip(summary.aligned, `cm_chip_align`)
                +     chip(summary.behaviourStrong, `cm_chip_behaviour`)
                +     chip(summary.satisfied, `cm_chip_satisfaction`)
                +   `</div>`
                +   (insights ? `<ul class="cpa-cm-insights">${insights}</ul>` : ``)
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.budgetBlown && ds.budgetSpent > this.BUDGET) return window.mySimulation.t(`hint_budget`);
            if (ds.orderTaking) return window.mySimulation.t(`hint_ordertaking`);
            if (ds.measurementCut && state.currentPeriod >= 3) return window.mySimulation.t(`hint_measurement`);
            if (ds.noApplication && state.currentPeriod >= 3) return window.mySimulation.t(`hint_application`);
            if (ds.risk >= 65) return window.mySimulation.t(`hint_risk`);
            if (ds.align >= 70 && ds.behaviour >= 65 && ds.budgetSpent <= this.BUDGET) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.align`, label: `Alignment`, i18nKey: `col_align`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.behaviour`, label: `Behaviour`, i18nKey: `col_behaviour`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.satisfaction`, label: `Satisfaction`, i18nKey: `col_satisfaction`, formatter: (v) => `${Math.round(v)}%` },
